<script setup lang="ts">
import { computed, ref } from 'vue'
import { ArrowRightIcon, CheckIcon, FeatherIcon, Trash2Icon } from '@lucide/vue'
import MoodPicker from '@/components/application/MoodPicker.vue'
import OverlayPanel from '@/components/common/OverlayPanel.vue'
import { localDay, moods, type MoodId, useWellbeingStore } from '@/stores/wellbeing'
const store = useWellbeingStore()
const selected = computed({ get: () => store.draftMood, set: value => { store.draftMood = value } })
const note = computed({ get: () => store.draftNote, set: value => { store.draftNote = value } })
const saved = ref(false)
const deleteId = ref('')
const page = ref(1)
const visibleEntries = computed(() => store.entries.slice(0, page.value * 10))
const week = computed(() => Array.from({ length: 7 }, (_, i) => {
  const date = new Date(); date.setDate(date.getDate() - 6 + i)
  const entry = store.entries.find(item => localDay(new Date(item.createdAt)) === localDay(date))
  return { date: date.getDate(), today: i === 6, mood: moods.find(item => item.id === entry?.mood), name: date.toLocaleDateString('zh-CN', { month: 'long', day: 'numeric' }) }
}))
const selectedMood = computed(() => moods.find(mood => mood.id === selected.value))
function save() { if (!selected.value) return; store.addEntry(selected.value, note.value); note.value = ''; selected.value = ''; saved.value = true }
function choose(value: MoodId) { selected.value = value; saved.value = false }
function remove() { store.removeEntry(deleteId.value); deleteId.value = '' }
const mood = (id: MoodId) => moods.find(item => item.id === id)!
</script>
<template>
  <div class="app-page mood-page"><p class="app-eyebrow">EVERY FEELING HAS A PLACE</p><h1>心情有晴雨，都值得记录。</h1><p class="app-subtitle">记下自己的天气，慢慢认识自己。这里没有好坏分数。</p>
    <div class="mood-layout"><section class="app-card mood-editor"><div class="mood-heading"><h2 class="app-section-title">留住此刻</h2><FeatherIcon :size="19" :stroke-width="1.4"/></div><MoodPicker :model-value="selected" @update:model-value="choose"/><p class="selected-response" aria-live="polite">{{ selectedMood?.reply || '今天的你，感觉怎么样？' }}</p><label for="mood-note">如果愿意，给今天留一句话<span>可选</span></label><textarea id="mood-note" v-model="note" maxlength="500" rows="4" placeholder="今天发生了什么？有什么想留给自己？" @input="saved = false"></textarea><div class="note-bottom"><span>{{ note.length }} / 500</span><button class="button primary" :disabled="!selected || saved" @click="save"><CheckIcon v-if="saved" :size="16"/>{{ saved ? '已记下这一刻' : '保存这份心情' }}<ArrowRightIcon v-if="!saved" :size="16"/></button></div><p class="local-note">心情记录只保存在当前浏览器，不会发送给模型。</p><p v-if="store.storageWarning" role="alert" class="save-warning">{{ store.storageWarning }}</p></section>
    <section class="week-card"><span class="week-flower" aria-hidden="true">✳</span><p class="app-eyebrow">YOUR OWN LITTLE WEATHER</p><h2>最近七天的天气</h2><p>空白的日子也没关系，<br/>从今天开始就很好。</p><div class="week-weather"><div v-for="day in week" :key="day.name" :class="{ today: day.today }" :aria-label="`${day.name}，${day.mood?.label || '还没有记录'}`"><span :style="{ background: day.mood ? `${day.mood.color}66` : '' }">{{ day.mood ? day.mood.face : '·' }}</span><small>{{ day.date }}</small></div></div><small>{{ store.recordedDays ? `已经留下 ${store.recordedDays} 天的心情，谢谢你照顾自己。` : '每一次停下来，都是一点温柔。' }}</small></section></div>
    <section class="mood-journal"><div class="journal-heading"><h2 class="app-section-title">写给自己的小片段</h2><span>{{ store.entries.length }} 条记录</span></div><div v-if="!store.entries.length" class="journal-empty"><FeatherIcon :size="30" :stroke-width="1.2"/><p>还没有留下心情记录。</p><span>不必写得完整，一句话也很好。</span></div><div v-else class="journal-entries"><article v-for="entry in visibleEntries" :key="entry.id" class="app-card journal-entry"><div class="journal-entry-heading"><span class="entry-mood" :style="{ background: `${mood(entry.mood).color}40` }">{{ mood(entry.mood).label }}</span><time :datetime="entry.createdAt">{{ new Date(entry.createdAt).toLocaleString('zh-CN', { month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' }) }}</time><button class="journal-delete" :aria-label="`删除${mood(entry.mood).label}心情记录`" @click="deleteId = entry.id"><Trash2Icon :size="15"/></button></div><p>{{ entry.note || mood(entry.mood).reply }}</p></article><button v-if="store.entries.length > visibleEntries.length" class="button load-more" @click="page++">再看看之前的心情</button></div></section>
    <OverlayPanel v-if="deleteId" title="删除这条心情记录？" @close="deleteId = ''"><p class="delete-description">这条记录会从当前浏览器移除，无法恢复。</p><div class="delete-actions"><button class="button" @click="deleteId = ''">先留着</button><button class="button danger" @click="remove">删除记录</button></div></OverlayPanel>
  </div>
</template>
<style scoped>
