lex;justify-content:space-between;align-items:center;margin-bottom:18px}.journal-heading>span{font-size:11px;color:#a0a791}.journal-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:180px;border:1px dashed #dce4d0;border-radius:18px;color:#b1bea0;background:#f5f7f0}.journal-empty p{margin:13px 0 5px;font-size:13px;color:#869579}.journal-empty>span{font-size:11px;color:#a0a791}.journal-entries{display:grid;gap:12px}.journal-entry{padding:18px 23px}.journal-entry-heading{display:flex;gap:13px;align-items:center}.entry-mood{font-size:11px;border-radius:7px;padding:4px 9px;color:#637157}.journal-entry time{font-size:10px;color:#9ea58e}.journal-delete{margin-left:auto;display:grid;place-items:center;min-width:44px;min-height:44px;border:0;background:transparent;color:#a7b09a}.journal-entry p{font-size:13px;line-height:1.9;margin:9px 0;color:#738269;white-space:pre-wrap;overflow-wrap:anywhere}.load-more{justify-self:center;margin-top:10px;font-weight:400}.delete-description{font-size:14px;color:var(--ink-soft)}.delete-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:24px}.danger{background:#f8e9e4;color:#a46554;border-color:#e3c5ba}@media(max-width:1050px){.mood-layout{grid-template-columns:1fr}.week-card{padding:26px}.week-weather{max-width:400px;margin:23px 0}.week-card>p:not(.app-eyebrow) br{display:none}.week-card h2{font-size:19px}}@media(max-width:767px){.mood-page h1{font-size:23px!important}.mood-editor{padding:20px}.mood-layout{margin-top:24px;gap:16px}.mood-editor .mood-heading{margin-bottom:14px}.selected-response{margin-bottom:23px}.week-card{padding:23px}.week-card h2{font-size:18px}.week-flower{font-size:48px}.week-weather{margin-bottom:20px}.mood-journal{margin-top:25px}.journal-entry{padding:14px 18px}.journal-entry-heading{gap:8px}.journal-entry time{font-size:9px}.local-note{font-size:10px;line-height:1.7}}
